hed','Returned','Completed'] as $s):?><option><?=e($s)?></option><?php endforeach?></select><input type="search" id="filter-destination" aria-label="Filter destination" placeholder="Search destination…"></div><div id="calendar-content" aria-live="polite"><div class="empty-state">Loading schedules…</div></div><div class="calendar-legend"><?php foreach(['blue'=>'Approved','purple'=>'Dispatched','green'=>'Returned / Completed'] as $c=>$s):?><span><i class="legend-dot <?=$c?>"></i><?=$s?></span><?php endforeach?><span class="legend-tip">Select a date to view its daily schedule</span></div></section><script src="assets/js/calendar.js" defer></script>
